#!/usr/bin/env bash
#
# Import-map gate — `importMap.js` must match the config that generates it.
#
# ## Why this exists
#
# `cms/src/app/(payload)/admin/importMap.js` is generated by
# `payload generate:importmap`, committed, and imported by the admin bundle. It is
# the map from a component *string* in `payload.config.ts` to a real module.
#
# That indirection is what makes it dangerous. A custom admin component is
# registered by path — `Upload: '@/components/media/OptimisedUpload
# #OptimisedUploadServer'` — and Payload resolves that string **through the import
# map**, not through Node. If the path is not in the committed map, Payload cannot
# load the component and **falls back to the default**. It does not throw.
#
# So the failure mode is silence. On 2026-10-11 the browser-side image optimiser
# was committed, deployed, and the upload still succeeded — it just silently did
# nothing, because the import map had never been regenerated. Typecheck, lint,
# build, CI and a manual upload test were all green while the feature was absent.
# Nothing in the pipeline could see it.
#
# This is the same bug class as `verify-payload-types.sh` one layer out: a
# generated file that is committed, imported, and can go stale while every other
# check stays green.
#
# ## Why `next build` does not cover this
#
# `cms/package.json` runs `next build`, not `generate:importmap`. Next bundles
# whatever import map is on disk, so a stale map builds cleanly and ships.
#
# ## How it detects drift
#
# Regenerate into the working tree and compare against the committed blob:
#
#   * identical -> PASS
#   * differs   -> FAIL, with the diff
#
# ## Why the committed content is snapshotted BEFORE generating
#
# The same ordering rule as `verify-payload-types.sh`. Regeneration overwrites the
# staleness, so capturing after generation would compare the generator against
# itself and could never fail.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

FILE="cms/src/app/(payload)/admin/importMap.js"

if [ ! -f "$FILE" ]; then
  echo "::error::$FILE is missing - Payload import-map generation has not run"
  echo "  pnpm --filter @shikkha24/cms generate:importmap"
  exit 1
fi

echo "-> capturing the committed import map, then regenerating"

# NOTE: ORDER IS THE WHOLE TRICK - see the header. Snapshot first, then generate,
# then compare. Generating first and diffing afterwards can never fail.
COMMITTED="$(mktemp)"
WORKTREE="$(mktemp)"

# Restore the working tree on every exit path, so a failing run never leaves a
# developer's checkout holding generated output.
cleanup() {
  git checkout -- "$FILE" 2>/dev/null || true
  rm -f "$COMMITTED" "$WORKTREE"
}
trap cleanup EXIT

if git cat-file -e "HEAD:$FILE" 2>/dev/null; then
  git cat-file blob "HEAD:$FILE" > "$COMMITTED"
else
  cp "$FILE" "$COMMITTED"
  echo "note: $FILE is not in HEAD yet - comparing against the working tree"
fi

PAYLOAD_BIN="$ROOT/cms/node_modules/.bin/payload"
if [ ! -x "$PAYLOAD_BIN" ]; then
  echo "::error::$PAYLOAD_BIN not found - run 'pnpm install' first"
  exit 1
fi

# A placeholder secret is enough: import-map generation reads the config, never
# the database.
(
  cd "$ROOT/cms"
  PAYLOAD_SECRET="${PAYLOAD_SECRET:-ci-placeholder-not-a-real-secret}" \
  DATABASE_URI="${DATABASE_URI:-file:./data/ci.db}" \
  NODE_OPTIONS=--no-deprecation \
    "$PAYLOAD_BIN" generate:importmap
) >/dev/null 2>&1 || {
  echo "::error::import-map generation failed - fix that before reading the diff below"
  echo "  cd cms && ./node_modules/.bin/payload generate:importmap"
  exit 1
}

cp "$FILE" "$WORKTREE"

if cmp -s "$COMMITTED" "$WORKTREE"; then
  echo "PASS  importMap.js matches what the config generates"
  exit 0
fi

echo "::error::$FILE is stale - a custom admin component path in the config is"
echo "        probably missing from it, and Payload falls back to the default"
echo "        component silently rather than failing."
echo
echo "Regenerate and commit it:"
echo "  pnpm --filter @shikkha24/cms generate:importmap"
echo
echo "--- what would change ---"
diff -u "$COMMITTED" "$WORKTREE" | head -40 || true
echo
echo "::error::an unresolved component path is a feature that does not exist while the build stays green. Commit the regenerated map."

git checkout -- "$FILE" 2>/dev/null || true
exit 1